import csv
import io
import re


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = []
    for row in reader:
        if any(cell.strip() for cell in row):
            records.append(row)

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 9
    number_pattern = re.compile(
        r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$|^[+-]?(?:inf|nan)$",
        re.IGNORECASE,
    )

    def header_score(row):
        width_score = -3 * abs(len(row) - expected_width)
        text_cells = sum(
            1
            for cell in row
            if cell.strip() and not number_pattern.fullmatch(cell.strip())
        )
        return width_score + 2 * text_cells

    header_index = max(range(len(records)), key=lambda i: (header_score(records[i]), -i))
    columns = list(records[header_index])
    data_records = records[header_index + 1:]

    width = max([len(columns)] + [len(row) for row in data_records])
    while len(columns) < width:
        columns.append("extra_" + str(len(columns) - len(records[header_index]) + 1))

    rows = []
    for record in data_records:
        normalized = list(record[:width])
        if len(normalized) < width:
            normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
